#include <bits/stdc++.h>
using namespace std;

const int MAX_LIMIT = 1050;
int Mod;
int add_mod(int a, int b) { return a + b >= Mod ? a + b - Mod : a + b; }
int diff_mod(int a, int b) { return a - b < 0 ? a - b + Mod : a - b; }
int prod_mod(int a, int b) { return (long long)a * b % Mod; }
void assign(int &a, int b) { a = add_mod(a, b); }

int C[MAX_LIMIT][MAX_LIMIT], f[MAX_LIMIT], g[MAX_LIMIT];
int n, m;

void compute_C(int n) {
    for (int i = 0; i <= n; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            C[i][j] = add_mod(C[i - 1][j - 1], C[i - 1][j]);
    }
}

int main() {
    cin >> n >> m >> Mod;
    f[1] = 2; g[1] = 0;
    int limit = max(m, n - m + 1);
    compute_C(limit);
    for (int i = 2; i <= m; ++i) {
        f[i] = prod_mod(f[i - 1], 2 * (i + 1));
        g[i] = prod_mod(g[i - 1], 2 * (i + 1));
        assign(g[i], prod_mod(f[i - 1], i * (i - 1)));
        for (int j = 1; j < i; ++j) {
            int k = i - j - 1;
            int c = prod_mod(C[j + k][j], j + k + 2);
            assign(f[i], prod_mod(c, prod_mod(f[j], f[k])));
            assign(g[i], prod_mod(c, prod_mod(f[j], g[k])));
            assign(g[i], prod_mod(c, prod_mod(g[j], f[k])));
            int w = j * (j + 1) / 2 + k * (k + 1) / 2;
            assign(g[i], prod_mod(prod_mod(C[j + k][j], w), prod_mod(f[j], f[k])));
        }
    }
    static int dp[MAX_LIMIT][MAX_LIMIT][2];
    memset(dp, 0, sizeof(dp));
    dp[0][0][0] = 1;
    for (int i = 0; i <= m; ++i)
        for (int j = 0; j <= m; ++j)
            for (int o = 0; o < 2; ++o) {
                int c = dp[i][j][o];
                if (c != 0) {
                    if (o == 0) {
                        for (int k = 1; k + j <= m; ++k) {
                            assign(dp[i + 1][j + k][0], prod_mod(prod_mod(c, C[j + k][k]), f[k]));
                            assign(dp[i + 1][j + k][1], prod_mod(prod_mod(c, C[j + k][k]), g[k]));
                        }
                    } else {
                        for (int k = 1; k + j <= m; ++k) {
                            assign(dp[i + 1][j + k][1], prod_mod(prod_mod(c, C[j + k][k]), f[k]));
                        }
                    }
                }
            }
    int total_ans = 0;
    for (int i = 1; i <= m; ++i)
        assign(total_ans, prod_mod(dp[i][m][1], C[n - m + 1][i]));
    cout << total_ans;
    return 0;
}
